const c = 299792458; // m/s, valor exacto por definición
const frecuenciasGHz = [1, 2, 3, 4, 5];

for (const g of frecuenciasGHz) {
  const periodoNs = 1 / g;                    // 1 / (g × 10^9) s = (1/g) ns
  const luzCm = c * (periodoNs * 1e-9) * 100; // metros → centímetros
  console.log(`${g} GHz: ciclo de ${periodoNs.toFixed(3)} ns, la luz avanza ${luzCm.toFixed(2)} cm`);
}

// Escala humana: 3 mil millones de ciclos, si cada ciclo durara un segundo
const segundosPorAnio = 365 * 24 * 3600;
console.log(`3e9 segundos = ${(3e9 / segundosPorAnio).toFixed(1)} años`);

// Espera a la memoria principal: 100 ns (orden de magnitud) a 3 GHz
console.log(`100 ns a 3 GHz = ${100 * 3} ciclos`);
